llm_calls.content:
{
  "task_summary": "Predict whether a person changed residence within the last year using individual ACS demographic, household, and work-related attributes in a way that should generalize across states.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is a strong, broadly stable driver of mobility over the life course across states."
    },
    {
      "rank": 2,
      "feature_id": 10,
      "rationale": "Household relationship strongly reflects life stage and household formation patterns closely tied to moving."
    },
    {
      "rank": 3,
      "feature_id": 2,
      "rationale": "Marital status is consistently linked to household transitions and relocation behavior."
    },
    {
      "rank": 4,
      "feature_id": 17,
      "rationale": "Employment status affects job-related moves and residential stability in a generally state-invariant way."
    },
    {
      "rank": 5,
      "feature_id": 1,
      "rationale": "Education captures life stage and labor-market position that predict migration across many contexts."
    },
    {
      "rank": 6,
      "feature_id": 20,
      "rationale": "Income influences housing options and moving propensity, though absolute levels vary by state."
    },
    {
      "rank": 7,
      "feature_id": 18,
      "rationale": "Usual work hours proxy job attachment and schedule stability, which relate to mobility."
    },
    {
      "rank": 8,
      "feature_id": 16,
      "rationale": "Class of worker captures employment arrangements associated with different relocation patterns."
    },
    {
      "rank": 9,
      "feature_id": 19,
      "rationale": "Commute time can motivate moves but is also shaped by local geography and infrastructure."
    },
    {
      "rank": 10,
      "feature_id": 9,
      "rationale": "Nativity is predictive of migration behavior but can partly reflect state-specific immigrant composition."
    },
    {
      "rank": 11,
      "feature_id": 6,
      "rationale": "Citizenship status adds migration-related signal beyond nativity, though it may encode regional composition."
    },
    {
      "rank": 12,
      "feature_id": 4,
      "rationale": "Disability status affects residential stability and moving constraints in a fairly general way."
    },
    {
      "rank": 13,
      "feature_id": 7,
      "rationale": "Military service can matter for relocation but applies to a smaller subgroup and may be episodic."
    },
    {
      "rank": 14,
      "feature_id": 15,
      "rationale": "Grandparent caregiving reflects family structure that may influence mobility, but it is niche."
    },
    {
      "rank": 15,
      "feature_id": 3,
      "rationale": "Sex may correlate with mobility through family and labor patterns, but effects are weaker and less direct."
    },
    {
      "rank": 16,
      "feature_id": 13,
      "rationale": "Cognitive difficulty may affect moving ability, though mostly through broader disability mechanisms already captured."
    },
    {
      "rank": 17,
      "feature_id": 11,
      "rationale": "Hearing difficulty has limited direct connection to moving beyond general health constraints."
    },
    {
      "rank": 18,
      "feature_id": 12,
      "rationale": "Vision difficulty is plausibly related to mobility decisions but usually only weakly."
    },
    {
      "rank": 19,
      "feature_id": 5,
      "rationale": "Parental employment status is mainly relevant for children and is less broadly informative for the full sample."
    },
    {
      "rank": 20,
      "feature_id": 14,
      "rationale": "Race can be predictive but risks demographic shortcutting and state-specific composition effects."
    },
    {
      "rank": 21,
      "feature_id": 8,
      "rationale": "Ancestry is especially likely to encode geography and local ethnic composition rather than stable causal signal."
    }
  ]
}
